'use client';
import { useEffect, useRef, useState, type CSSProperties } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useReducedMotion } from '../lib/hooks';
import { Seg, Swap, Tip } from '../lib/motion';
import '../designme.css';
import './activity-heatmap.css';

export interface ActivityHeatmapSeries {
  key: string;
  /** The switch label, like "Agent" */
  label: string;
  /** 168 values from 0 to 1, one an hour, Monday 12am first */
  values: number[];
  /** What a full cell counts, for the tips, like 40 */
  max: number;
  /** What it counts, for the tips, like "runs" */
  unit: string;
  /** The line under the title while this series shows, like "Busiest overnight, when the queue runs" */
  note?: string;
}

export interface ActivityHeatmapProps {
  /** One or more series; the switch shows when there are two or more */
  series: ActivityHeatmapSeries[];
  /** The series on show, by key. Leave it out to let the switch pick it */
  value?: string;
  defaultValue?: string;
  onValueChange?: (key: string) => void;
  /** Header text */
  title?: string;
  /** The line under the title before the cells fill in, and when a series has no note */
  period?: string;
  className?: string;
}

const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const LEGEND = [.08, .3, .55, .85];
// every three hours; the ones between the four on a wide card only show on a phone
const HOURS = ['12am', '3am', '6am', '9am', '12pm', '3pm', '6pm', '9pm'];
const hour = (h: number) => (h % 12 || 12) + (h < 12 ? 'am' : 'pm');
const shade = (a: number): CSSProperties => ({ ['--dm-a' as string]: a });

/** When the agent or the team is busy, by day and hour. The cells fill in as a wave from the top left. In a narrow card (a phone)
    the grid shows half the day at a time in bigger cells, scrolls sideways and starts at the latest hours. */
export function ActivityHeatmap({ series, value, defaultValue, onValueChange, title = 'Activity', period = 'Last 4 weeks', className }: ActivityHeatmapProps) {
  const [key, setKey] = useControllable(value, defaultValue ?? series[0]?.key ?? '', onValueChange);
  const s = series.find(x => x.key === key) ?? series[0];
  const reduce = useReducedMotion();
  // the cells start empty and fill in a moment after the card appears
  const [drawn, setDrawn] = useState(false);
  useEffect(() => { const t = setTimeout(() => setDrawn(true), 150); return () => clearTimeout(t); }, []);
  // on a phone the grid scrolls sideways: it starts at the latest hours, and fades out on whichever side has more to see
  const sc = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const el = sc.current; if (!el) return;
    // it stays on the latest hours as the card settles its size, until the person scrolls it themselves
    let moved = false;
    const edges = () => { const m = el.scrollWidth - el.clientWidth; el.classList.toggle('dm-ml', m > 1 && el.scrollLeft > 1); el.classList.toggle('dm-mr', m > 1 && el.scrollLeft < m - 1); };
    const fit = () => { if (!moved) el.scrollLeft = el.scrollWidth; edges(); };
    const move = () => { moved = true; }, EV = ['pointerdown', 'wheel', 'touchstart', 'keydown'] as const;
    const ro = new ResizeObserver(fit); ro.observe(el); const g = el.querySelector('.dm-hmx-grid'); if (g) ro.observe(g); el.addEventListener('scroll', edges, { passive: true });
    EV.forEach(e => el.addEventListener(e, move, { passive: true }));
    return () => { ro.disconnect(); el.removeEventListener('scroll', edges); EV.forEach(e => el.removeEventListener(e, move)); };
  }, []);

  return (
    <div data-dm="" className={cx('dm-hmx dm-panel', className)}>
      <div className="dm-hmx-h">
        <div><b>{title}</b><Swap className="dm-muted dm-hmx-st">{drawn ? s?.note ?? period : period}</Swap></div>
        {series.length > 1 && <Seg className="dm-hmx-sg" label="Who" value={key} onChange={setKey} options={series.map(x => ({ value: x.key, label: x.label }))} />}
      </div>
      <div className="dm-hmx-wrap"><div ref={sc} className="dm-hmx-sc">
        <div className="dm-hmx-days dm-muted" aria-hidden="true">{['Mon', '', 'Wed', '', 'Fri', '', 'Sun'].map((d, i) => <span key={i}>{d}</span>)}</div>
        <div className="dm-hmx-grid" role="img" aria-label={`${title}, ${s?.note ?? period}`}>
          {Array.from({ length: 168 }, (_, i) => {
            const d = Math.floor(i / 24), h = i % 24, v = s?.values[i] ?? 0;
            // each cell changes a beat after the one before it, so a new series sweeps in from the top left
            const style = { ...shade(drawn ? +(v * .9).toFixed(2) : 0), transition: `background .5s var(--dm-ease) ${reduce ? 0 : (h + d) * 14}ms, transform .2s` };
            // always inside its Tip, so the cell keeps its element (and its transition) when the tips switch on
            return <Tip key={i} off={!drawn} label={s ? `${DAYS[d]} ${hour(h)}: ${Math.round(v * s.max)} ${s.unit}` : ''}><i style={style} /></Tip>;
          })}
        </div>
        <div className="dm-hmx-f dm-muted" aria-hidden="true">{HOURS.map((t, i) => <span key={t} className={cx('dm-hmx-ax', i % 2 === 1 && 'dm-x')}>{t}</span>)}</div>
      </div></div>
      <div className="dm-hmx-lg dm-muted" aria-hidden="true">Less{LEGEND.map(a => <i key={a} style={shade(a)} />)}More</div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Activity heatmap ---------- */
.dm-hmx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:10px}
/* the ramp (owner, 20 Nov: "saturate the greens and blues"): from a light tint of the chart's mark colour to that colour at
   full strength, mixed in oklch so the steps between stay vivid rather than greying. The busiest cells, and the key's More,
   are the mark colour a touch toward the text, so they keep 3:1 on the card with room to spare (the blue in Soft and Clean,
   Blueprint's green in light and its lime in dark), and the key shows the same ramp as the cells. In dark mode the quiet end
   is a deeper tint, so it still reads against the card */
.dm-hmx{--dm-hm-hi:color-mix(in oklch,var(--dm-accent-mark,var(--dm-accent)) 92%,var(--dm-fg));--dm-hm-lo:color-mix(in oklch,var(--dm-hm-hi) 13%,var(--dm-surface))}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .dm-hmx{--dm-hm-lo:color-mix(in oklch,var(--dm-hm-hi) 22%,var(--dm-surface))}}
:root[data-theme="dark"] .dm-hmx{--dm-hm-lo:color-mix(in oklch,var(--dm-hm-hi) 22%,var(--dm-surface))}
/* the head sits over a hairline in every style (owner, 21 Nov), 10px from it on each side as the card's other gaps */
.dm-hmx-h{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-bottom:10px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-hmx-h>div:first-child{display:flex;flex-direction:column;font-size:13.5px;line-height:1.4}
.dm-hmx-h b{font-weight:500}
.dm-hmx-st{font-size:12px}
.dm-hmx-sg button{font-size:12px;height:26px;padding:0 9px}
/* the day names, the cells and the hour names sit in one grid, so the hour names line up with the cells; on a phone the
   grid scrolls sideways (below) and the day names stay put */
.dm-hmx-sc{display:grid;grid-template-columns:auto minmax(0,1fr);gap:6px}
.dm-hmx-days{display:grid;grid-template-rows:repeat(7,1fr);gap:3px;font-size:10px}
.dm-hmx-days span{display:flex;align-items:center;height:100%}
.dm-hmx-grid{display:grid;grid-template-columns:repeat(24,minmax(0,1fr));gap:3px;min-width:0}
.dm-hmx-grid i{aspect-ratio:1;border-radius:var(--dm-r-tiny,3px);background:color-mix(in oklch,var(--dm-hm-hi) min(var(--dm-a) * 118%,100%),var(--dm-hm-lo));transition:background .5s var(--dm-ease),transform .2s;max-width:100%}
@media (hover:hover) and (pointer:fine){.dm-hmx-grid i:hover{transform:scale(1.35);box-shadow:0 0 0 1.5px var(--dm-surface);position:relative;z-index:1}}
.dm-hmx-f{grid-column:2;display:grid;grid-template-columns:repeat(4,1fr);font-size:10.5px}
.dm-hmx-f .dm-x{display:none}
/* phones, and narrow cards: the grid scrolls sideways by touch or trackpad in 20px cells (about half the day on a phone, a
   little more on a wider card, never bigger cells for a wider card), starting at the latest hours. The edge the grid runs on
   past fades out, and the hour names come every three hours */
.dm-hmx{container-type:inline-size}
@container (max-width:400px){
  .dm-hmx-sc{grid-template-columns:34px calc(24 * 20px + 23 * 4px);column-gap:0;overflow-x:auto;overscroll-behavior-x:contain;scrollbar-width:none;scroll-snap-type:x proximity;scroll-padding-left:34px;
    --dm-fl:0px;--dm-fr:0px;-webkit-mask-image:linear-gradient(to right,#000 34px,transparent 34px,#000 calc(34px + var(--dm-fl)),#000 calc(100% - var(--dm-fr)),transparent);mask-image:linear-gradient(to right,#000 34px,transparent 34px,#000 calc(34px + var(--dm-fl)),#000 calc(100% - var(--dm-fr)),transparent)}
  .dm-hmx-sc::-webkit-scrollbar{display:none}
  .dm-hmx-sc.dm-ml{--dm-fl:16px}.dm-hmx-sc.dm-mr{--dm-fr:16px}
  .dm-hmx-days{position:sticky;left:0;z-index:2;background:var(--dm-surface);gap:4px;padding-right:6px;font-size:10.5px}
  /* and the corner under the day names covers the hour names as they scroll past */
  .dm-hmx-sc::after{content:"";grid-row:2;grid-column:1;position:sticky;left:0;z-index:2;background:var(--dm-surface)}
  .dm-hmx-grid{gap:4px}
  .dm-hmx-grid i{border-radius:calc(4px * var(--dm-rk-s,var(--dm-rk)));scroll-snap-align:start}
  .dm-hmx-f{grid-template-columns:repeat(8,1fr)}
  .dm-hmx-f .dm-x{display:block}
}
.dm-hmx-lg{align-self:flex-end;display:flex;align-items:center;gap:3px;font-size:10.5px;line-height:1.2}
/* the key's squares are the cells a size down: the same shades, and corners as round for their size */
.dm-hmx-lg i{width:9px;height:9px;border-radius:calc(var(--dm-r-tiny,2.67px) * .75);background:color-mix(in oklch,var(--dm-hm-hi) min(var(--dm-a) * 118%,100%),var(--dm-hm-lo))}
/* Clean (owner, 17 and 18 Nov): the content 16px in from every edge, and a cell under the pointer is ringed in a quiet grey
   rather than growing */
:root[data-style="clean"] .dm-hmx.dm-panel,:root [data-style="clean"] .dm-hmx.dm-panel,:root [data-style="clean"].dm-hmx.dm-panel{padding:16px}
:root[data-style="clean"] .dm-hmx-h,:root [data-style="clean"] .dm-hmx-h,:root [data-style="clean"].dm-hmx-h{border-bottom-color:var(--dm-line)}
/* Clean: the Less to More key sits in the card's off-white foot strip, its words 16px in (owner, 21 Nov) */
:root[data-style="clean"] .dm-hmx.dm-panel .dm-hmx-lg,:root [data-style="clean"] .dm-hmx.dm-panel .dm-hmx-lg,:root [data-style="clean"].dm-hmx.dm-panel .dm-hmx-lg{align-self:stretch;justify-content:flex-end;min-height:calc(28px + 2 * var(--dm-strip-y) + 1px);margin:6px -16px -16px;padding:0 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .dm-hmx-grid i,:root [data-style="clean"] .dm-hmx-grid i,:root [data-style="clean"].dm-hmx-grid i{transition:background .5s var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-hmx-grid i:hover,:root [data-style="clean"] .dm-hmx-grid i:hover,:root [data-style="clean"].dm-hmx-grid i:hover{transform:none;box-shadow:0 0 0 1px var(--dm-surface),0 0 0 2.5px var(--dm-line-strong)}}
